Component(
  dsl: 1, id: "market/store-directory", name: "Store directory", kind: Kind.storeInfo,
  description: "Every store near the customer with its city and whether it's open.",
  variants: [Variant(id: "default", label: "Default", build:
    Column(gap: Space.sm, children: [
      ForEach(items: stores.results, as: "s", empty: Text(child: "No stores near you yet.", color: Color.textMuted), child: Box(padding: Space.md, radius: Radius.md, background: Color.surface, border: Border(width: 1), child: Row(gap: Space.md, crossAxisAlignment: CrossAxisAlignment.center, children: [
        Box(shape: BoxShape.circle, width: 40, height: 40, alignment: Anchor.center, background: Color.surfaceAlt, child: Icon(name: Icons.location, color: Color.primary)),
        Expanded(child: Column(gap: Space.xs, children: [Text(child: s.name, weight: FontWeight.semibold), Text(child: s.city, size: FontSize.sm, color: Color.textMuted)])),
        If(condition: s.is_open, then: Badge(label: "Open", tone: Tone.success), else: Badge(label: "Closed", tone: Tone.neutral))
      ])))
    ])
  )], data: [Data(name: "stores", from: Client.stores(), fetch: "client", type: StoreSearch)],
)
